index 096e099391..9cfbd4fe7c 100644
--- a/servers/rendering/renderer_rd/shaders/forward_clustered/scene_forward_clustered.glsl
+++ b/servers/rendering/renderer_rd/shaders/forward_clustered/scene_forward_clustered.glsl
@@ -2756,7 +2756,7 @@ void fragment_shader(in SceneData scene_data) {
 #endif

 #ifndef FOG_DISABLED
-	diffuse_buffer.rgb = mix(diffuse_buffer.rgb, fog.rgb, fog.a);
+	diffuse_buffer.rgb = diffuse_buffer.rgb * (1.0 - fog.a) + fog.rgb;
 	specular_buffer.rgb = mix(specular_buffer.rgb, vec3(0.0), fog.a);
 #endif //!FOG_DISABLED

@@ -2773,7 +2773,7 @@ void fragment_shader(in SceneData scene_data) {

 #ifndef FOG_DISABLED
 	// Draw "fixed" fog before volumetric fog to ensure volumetric fog can appear in front of the sky.
-	frag_color.rgb = mix(frag_color.rgb, fog.rgb, fog.a);
+	frag_color.rgb = frag_color.rgb * (1.0 - fog.a) + fog.rgb;
 #endif //!FOG_DISABLED

 #endif //MODE_SEPARATE_SPECULAR
```

this has volumetrics looking the way i expect, not sure if/how this messes with non-volumetric fog as well (i haven't tested, i'm only using volumetric in my game)

> Note that the proposed change removes the influence of `fog_sky_affect`, which is incorrect as we should keep it as part of the equation. A value of `0.0` makes it not affect the sky at all, `1.0` makes it act like the proposed change, and intermediate values should blend between both states.

nice catch, i didn't intend to touch that.

with that i decided to think a little harder about the interacting options, this one seems to work right in every configuration i've tried (regular, volumetric, both, playing with the sky affect and aerial perspective options).

```diff
diff --git a/servers/rendering/renderer_rd/shaders/environment/sky.glsl b/servers/rendering/renderer_rd/shaders/environment/sky.glsl
index 6f8d5e1909..b6474d92bd 100644
