@@ -1421,15 +1421,9 @@ void fragment_shader(in SceneData scene_data) {
 #endif
 		if (bool(scene_data.flags & SCENE_DATA_FLAGS_USE_FOG)) {
 			//must use the full blending equation here to blend fogs
-			vec4 res;
 			float sa = 1.0 - volumetric_fog.a;
-			res.a = fog.a * sa + volumetric_fog.a;
-			if (res.a == 0.0) {
-				res.rgb = vec3(0.0);
-			} else {
-				res.rgb = (fog.rgb * fog.a * sa + volumetric_fog.rgb * volumetric_fog.a) / res.a;
-			}
-			fog = res;
+			fog.rgb = fog.rgb * sa + volumetric_fog.rgb;
+			fog.a = fog.a * sa + volumetric_fog.a;
 		} else {
 			fog = volumetric_fog;
 		}
```

way later edit: here's the patch as i've been using it for some months now

i've revisited this now that my game uses various combinations of volumetric and regular fog. i'm not aware of any remaining issues (tested with either of them on/off, sky affect, aerial perspective and height density and no cases seem either over-bright or over-dark for me).

hopefully that's everything sorted out (and maybe, just maybe, this can make it into a release at some point)

